using Dapper; using InovaGed.Application.Common.Database; using InovaGed.Application.Continuity;
namespace InovaGed.Infrastructure.Continuity;
public sealed class TenantOffboardingRepository(IDbConnectionFactory db) : ITenantOffboardingService
{
 public async Task<IReadOnlyList<TenantOffboardingDto>> ListAsync(Guid? tenantId,CancellationToken ct){await using var c=await db.OpenAsync(ct);var rows=await c.QueryAsync<TenantOffboardingDto>(new CommandDefinition("select id, tenant_id TenantId, status, started_at_utc StartedAtUtc, effective_at_utc EffectiveAtUtc, access_until_utc AccessUntilUtc, legal_hold LegalHold, justification from ged.tenant_offboarding where (@tenantId is null or tenant_id=@tenantId)",new{tenantId},cancellationToken:ct));return rows.AsList();}
 public async Task<TenantOffboardingDto> StartAsync(Guid tenantId,DateTime effectiveAtUtc,string justification,string requestedBy,CancellationToken ct){ArgumentException.ThrowIfNullOrWhiteSpace(justification);await using var c=await db.OpenAsync(ct);var id=Guid.NewGuid();var access=effectiveAtUtc.AddDays(90);await c.ExecuteAsync(new CommandDefinition("insert into ged.tenant_offboarding(id,tenant_id,status,effective_at_utc,access_until_utc,justification,requested_by) values(@id,@tenantId,'DRAFT',@effectiveAtUtc,@access,@justification,@requestedBy)",new{id,tenantId,effectiveAtUtc,access,justification,requestedBy},cancellationToken:ct));return new(id,tenantId,"DRAFT",DateTime.UtcNow,effectiveAtUtc,access,false,justification);}
 public async Task<RestoreValidationResult> ApproveDeletionAsync(Guid offboardingId,string justification,CancellationToken ct){ArgumentException.ThrowIfNullOrWhiteSpace(justification);await using var c=await db.OpenAsync(ct);var blocked=await c.QuerySingleAsync<bool>(new CommandDefinition("select coalesce((select legal_hold from ged.tenant_offboarding where id=@offboardingId),true)",new{offboardingId},cancellationToken:ct));return blocked?new(false,"Legal hold ou registro inexistente bloqueia avanço."):new(false,"Exclusão física automática permanece desabilitada.");}
}
